// Desktop 2.0 snapshot: src/shared/lyrics.ts. Generated by scripts/import-pc-2.mjs; platform adaptations are explicit in that script.
// Тексты песен (версия 1.6): общие для главного процесса и окна типы и чистые функции
// (разбор LRC, строка по времени, можно ли включать подсветку). Проверяются тестами tests/lyrics.test.ts.

/** Одна строка синхронного текста: время начала в мс и текст ('' = пауза, «♪» = инструментальная часть). */
export interface LyricLine {
  t: number;
  text: string;
}

/** «файл .lrc»: свой файл с текстом рядом с песней (1.7). */
export type LyricsSource = 'YouTube Music' | 'LRCLIB' | 'файл .lrc';

export type LyricsResult =
  | {
      kind: 'synced';
      lines: LyricLine[];
      source: LyricsSource;
      /** Длительность песни, к которой относится текст (с), если известна: для сверки с играющей версией. */
      srcDuration: number | null;
      /** Ручной сдвиг человека для этой песни, мс (плюс: текст позже). */
      offsetMs: number;
    }
  | { kind: 'plain'; text: string; source: LyricsSource; offsetMs: number }
  | { kind: 'instrumental'; source: LyricsSource; offsetMs: number }
  | { kind: 'none'; offsetMs: number };

/** Расхождение длительности, после которого подсветку не включаем (текст от другой версии песни). */
export const SYNC_TOLERANCE_S = 3;

const TAG = /\[(\d{1,3}):(\d{1,2})(?:[.:](\d{1,3}))?\]/g;

/**
 * Разбор LRC: несколько меток на строку («[00:12.00][01:30.50]припев»), метка [offset:±мс],
 * пустые строки (паузы), служебные метки ([ar:], [ti:]...) пропускаются. Строки по времени.
 */
export function parseLrc(text: string): LyricLine[] {
  let offset = 0;
  const out: LyricLine[] = [];
  for (const raw of String(text ?? '').split(/\r?\n/)) {
    const line = raw.trim();
    const off = /^\[offset:\s*([+-]?\d+)\s*\]$/i.exec(line);
    if (off) {
      // По стандарту LRC положительный offset означает «текст раньше»
      offset = Number(off[1]);
      continue;
    }
    const times: number[] = [];
    let m: RegExpExecArray | null;
    TAG.lastIndex = 0;
    let rest = line;
    while ((m = TAG.exec(line))) {
      const frac = m[3] ? Number(m[3].padEnd(3, '0').slice(0, 3)) : 0;
      times.push((Number(m[1]) * 60 + Number(m[2])) * 1000 + frac);
      rest = line.slice(TAG.lastIndex);
    }
    if (!times.length) continue;
    const words = rest.replace(/<\d{1,2}:\d{2}(?:\.\d{1,3})?>/g, '').trim(); // слова с метками внутри строки (enhanced LRC)
    for (const t of times) out.push({ t, text: words });
  }
  return out.map((l) => ({ ...l, t: Math.max(0, l.t - offset) })).sort((a, b) => a.t - b.t);
}

/** Номер текущей строки для времени timeMs (бинарный поиск): последняя строка с t <= timeMs, -1 до первой. */
export function lineAt(lines: LyricLine[], timeMs: number): number {
  let lo = 0;
  let hi = lines.length - 1;
  let ans = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (lines[mid].t <= timeMs) {
      ans = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return ans;
}

/**
 * Включать ли подсветку: длительность источника текста и играющего звука отличаются не больше чем на 3 с.
 * Если длительность источника неизвестна (текст той же записи YouTube Music), подсветка разрешена.
 */
export function canSync(srcDuration: number | null | undefined, playDuration: number | null | undefined): boolean {
  if (!srcDuration || !playDuration || !Number.isFinite(playDuration)) return true;
  return Math.abs(srcDuration - playDuration) <= SYNC_TOLERANCE_S;
}

/** Время для подсветки: время плеера (с) плюс ручной сдвиг (мс; плюс = текст позже, то есть строки сдвигаются). */
export const lyricTime = (currentTimeS: number, offsetMs: number) => currentTimeS * 1000 - offsetMs;

/** Ключ песни для кэша и сдвига. */
export const lyricsKey = (c: { source: string; id: string }) => `${c.source}:${c.id}`;
